CREATE TABLE p_disputes(id TEXT PRIMARY KEY,payment_id TEXT NOT NULL REFERENCES p_payment_records(id),status TEXT NOT NULL,deadline INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,imported_by TEXT NOT NULL REFERENCES oa_operators(id),imported_at INTEGER NOT NULL);
CREATE TABLE p_dispute_submissions(id TEXT PRIMARY KEY,dispute_id TEXT NOT NULL REFERENCES p_disputes(id),note TEXT NOT NULL,document_hash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('reserved','submitted','needs_review')),submitted_by TEXT NOT NULL REFERENCES oa_operators(id),submitted_at INTEGER NOT NULL);
CREATE TABLE p_dispute_documents(submission_id TEXT NOT NULL REFERENCES p_dispute_submissions(id),part INTEGER NOT NULL,base64 TEXT NOT NULL,PRIMARY KEY(submission_id,part));
